<?php
namespace App\Http\Controllers;
use App\Models\Seller;use App\Models\SellerStaff;use App\Models\Admin;use App\Mail\StaffInvitedMail;use App\Services\PasswordResetCodeService;use Illuminate\Support\Facades\Mail;use Illuminate\Http\Request;use Illuminate\Http\JsonResponse;use Illuminate\Validation\Rule;
class SellerStaffController extends Controller{
 private function owner(Request $r):Seller{abort_unless(!$r->attributes->has('seller_staff') && $r->user() instanceof Seller,403);return $r->user();}
 private function data(Request $r,bool $new=false):array{return $r->validate(['name'=>[$new?'required':'sometimes','string','max:255'],'email'=>[$new?'required':'sometimes','email','max:255',Rule::unique('seller_staff')->ignore($r->route('staff'))],'phone'=>['sometimes','nullable','string','max:32'],'status'=>['sometimes',Rule::in(['active','suspended'])]]);}
 public function index(Request $r):JsonResponse{return response()->json($this->owner($r)->staff()->latest()->get());}
 public function store(Request $r):JsonResponse{$seller=$this->owner($r);$d=$this->data($r,true);$d['status']=($d['status']??'active')==='suspended'?'suspended':'invited';$staff=$seller->staff()->create($d);if($staff->status==='invited')$this->invite($staff,$seller);return response()->json($staff,201);}
 public function update(Request $r,SellerStaff $staff):JsonResponse{abort_unless($staff->seller_id===$this->owner($r)->id,404);$d=$this->data($r);if(($d['status']??null)==='active'&&$staff->status==='invited')unset($d['status']);$staff->update($d);if(($d['status']??null)==='suspended')$staff->tokens()->delete();return response()->json($staff->fresh());}
 public function destroy(Request $r,SellerStaff $staff):JsonResponse{abort_unless($staff->seller_id===$this->owner($r)->id,404);$staff->tokens()->delete();$staff->delete();return response()->json(['message'=>'Staff removed.']);}
 public function adminIndex(Request $r):JsonResponse{abort_unless($r->user() instanceof Admin,403);return response()->json(SellerStaff::with('seller:id,store_name,store_slug')->when($r->query('seller_id'),fn($q,$id)=>$q->where('seller_id',$id))->latest()->paginate(25));}
 public function adminStore(Request $r,Seller $seller):JsonResponse{abort_unless($r->user() instanceof Admin,403);$d=$this->data($r,true);$d['status']=($d['status']??'active')==='suspended'?'suspended':'invited';$staff=$seller->staff()->create($d);if($staff->status==='invited')$this->invite($staff,$seller);return response()->json($staff->load('seller:id,store_name,store_slug'),201);}
 public function adminUpdate(Request $r,SellerStaff $staff):JsonResponse{abort_unless($r->user() instanceof Admin,403);$d=$this->data($r);$d+= $r->validate(['seller_id'=>['sometimes','integer','exists:sellers,id']]);$staff->update($d);if(($d['status']??null)==='suspended')$staff->tokens()->delete();return response()->json($staff->fresh()->load('seller:id,store_name,store_slug'));}
 public function adminDestroy(Request $r,SellerStaff $staff):JsonResponse{abort_unless($r->user() instanceof Admin,403);$staff->tokens()->delete();$staff->delete();return response()->json(['message'=>'Staff removed.']);}
 private function invite(SellerStaff $staff,Seller $seller):void{$code=app(PasswordResetCodeService::class)->issue($staff,'seller_staff');Mail::to($staff->email)->send(new StaffInvitedMail($staff->name,$staff->email,$seller->store_name,$code));}
 public function me(Request $r):JsonResponse{$staff=$r->attributes->get('seller_staff');abort_unless($staff instanceof SellerStaff,403);$d=$r->validate(['name'=>['sometimes','string','max:255'],'email'=>['sometimes','email','max:255',Rule::unique('seller_staff')->ignore($staff->id)],'phone'=>['sometimes','nullable','string','max:32'],'image'=>['sometimes','file','image','max:5120'],'clear_image'=>['sometimes','boolean']]);if(!empty($d['clear_image']))$d['image']=null;if($r->hasFile('image'))$d['image']=app(\App\Services\MediaUploadService::class)->upload($r->file('image'));unset($d['clear_image']);$staff->update($d);return response()->json(['message'=>'Profile updated.','staff'=>$staff->fresh()]);}
 public function password(Request $r):JsonResponse{$staff=$r->attributes->get('seller_staff');abort_unless($staff instanceof SellerStaff,403);$d=$r->validate(['current_password'=>['required','string'],'new_password'=>['required','string','min:8','confirmed']]);if(!\Illuminate\Support\Facades\Hash::check($d['current_password'],$staff->password??''))return response()->json(['message'=>'Current password is incorrect.'],422);$staff->update(['password'=>$d['new_password']]);$staff->tokens()->delete();app(\App\Services\AccountSecurityMailService::class)->passwordChanged($staff,'settings',$r->ip());return response()->json(['message'=>'Password updated successfully.']);}

 public function emailCurrent(Request $r,\App\Services\EmailChangeService $s):JsonResponse{$staff=$r->attributes->get('seller_staff');abort_unless($staff instanceof SellerStaff,403);return response()->json($s->sendCurrent($staff));}
 public function emailVerifyCurrent(Request $r,\App\Services\EmailChangeService $s):JsonResponse{$staff=$r->attributes->get('seller_staff');$d=$r->validate(['code'=>['required','digits:6']]);return response()->json($s->verifyCurrent($staff,$d['code']));}
 public function emailRequest(Request $r,\App\Services\EmailChangeService $s):JsonResponse{$staff=$r->attributes->get('seller_staff');$d=$r->validate(['email'=>['required','email','max:255']]);return response()->json($s->request($staff,$d['email']));}
 public function emailVerifyNew(Request $r,\App\Services\EmailChangeService $s):JsonResponse{$staff=$r->attributes->get('seller_staff');$d=$r->validate(['code'=>['required','digits:6']]);return response()->json(['message'=>'Email updated.','staff'=>$s->verifyNew($staff,$d['code'])]);}
 public function emailResend(Request $r,\App\Services\EmailChangeService $s):JsonResponse{$staff=$r->attributes->get('seller_staff');$d=$r->validate(['step'=>['required','in:current,new']]);return response()->json($s->resend($staff,$d['step']));}
}
